  'inquiries.suggest.received.text': 'உங்கள் செய்திக்கு நன்றி. அதைப் பெற்றுக்கொண்டோம், அதைப் பற்றிப் பார்க்கிறோம்.',
  'inquiries.suggest.checking': 'சரிபார்க்கிறோம்',
  'inquiries.suggest.checking.text': 'இதைச் சரிபார்த்துக்கொண்டிருக்கிறோம், விரைவில் உங்களுக்குப் பதிலளிப்போம்.',
  'inquiries.suggest.visitOffice': 'அலுவலகம் வாருங்கள்',
  'inquiries.suggest.visitOffice.text': 'உங்களுக்கு உதவ, உங்கள் கணக்குப் புத்தகம் மற்றும் தேசிய அடையாள அட்டையுடன் தொழிற்சாலை அலுவலகத்திற்கு வாருங்கள்.',
