  'content.restoreDefaultBody': 'ஒவ்வொரு தொழிற்சாலையும் தொடங்கும் உரையால், உங்கள் தொழிற்சாலையின் பெயருடன், படிவம் நிரப்பப்படும். தற்போது படிவத்தில் உள்ளது மாற்றப்படும். நீங்கள் சேமி அழுத்தும் வரை செயலியில் எதுவும் மாறாது, எனவே சேமிக்காமல் வெளியேறலாம்.',
