  'config.sectionDescription.notes': 'முடிவு மற்றும் பதில் பெட்டிகளின் கீழ் காட்டப்படும் தயாரான வாக்கியங்கள், உங்கள் தொழிற்சாலையின் சொந்த வார்த்தைகளில்.',
  'config.notes.intro': 'ஒவ்வொரு பட்டியலும் ஒரு பெட்டியின் கீழ் காட்டப்படும். ஒரு chip க்குச் சிறிய பெயரும் அது சேர்க்கும் வாக்கியமும் உண்டு; உங்கள் அலுவலகம் பயன்படுத்தும் ஒவ்வொரு மொழிக்கும் இரண்டையும் எழுதுங்கள். காலியான பட்டியல் உள்ளமைந்த வாக்கியங்களைப் பயன்படுத்தும்.',
  'config.notes.list': 'பட்டியல்',
  'config.notes.language': 'மொழி',
  'config.notes.usingBuiltIn': 'இந்தப் பட்டியல் காலியாக உள்ளது, எனவே உள்ளமைந்த வாக்கியங்கள் பயன்படுத்தப்படுகின்றன. உங்களுடையதைப் பயன்படுத்த ஒரு chip ஐச் சேர்க்கவும்.',
