  'config.manureProductsHint':
    'பெயர், ஒரு மூட்டையில் உள்ள கிலோ, மற்றும் ஒரு மூட்டையின் விலை. கோரிக்கை இந்தப் பட்டியலிலிருந்து விலை நிர்ணயிக்கப்படுகிறது. அலுவலகம் ஒருபோதும் தொகையைத் தட்டச்சு செய்வதில்லை, எனவே சப்ளையர் தமக்கு வசூலிக்கப்பட்டதை இதனுடன் சரிபார்க்கலாம்.',
