  'uploads.unavailable': 'இந்த சேவையகத்தில் பட சேமிப்பு இன்னும் அமைக்கப்படவில்லை, எனவே படங்களைப் பதிவேற்ற முடியாது. மற்ற அனைத்தும் இயல்பாகச் சேமிக்கப்படும்.',
  'uploads.error.upload-type': 'அந்த கோப்பு வகையைப் பயன்படுத்த முடியாது. JPEG, PNG அல்லது WebP ஒன்றைத் தேர்ந்தெடுக்கவும்.',
  'uploads.error.upload-too-large': 'அந்தப் படம் {{max}} MB ஐ விட பெரியது. சிறியதைத் தேர்ந்தெடுக்கவும்.',
