  /* ───────────────────────────── M16 Reports ───────────────────────────── */
  /* The list is short on purpose and the copy says so: §19.1's warehouse shape is what the
     rest of M16 needs, and §19.1 is not in this repository. */
  'reports.title': 'அறிக்கைகள்',
  'reports.tab.appUse.hint': 'வழங்குநர்கள் அலுவலகக் கவுண்டரிலிருந்து செயலிக்கு மாறுகிறார்களா? ஒவ்வொரு கோரிக்கையும், அது செய்யப்பட்ட இடத்தின்படி எண்ணப்படுகிறது.',
  'reports.tab.savings.hint': 'தொழிற்சாலை வழங்குநர்களுக்காக வைத்திருக்கும் தொகை, ஒவ்வொரு மாதமும் வந்தது மற்றும் போனது. தொழிற்சாலை அமைப்பில் வைக்கப்பட்டு, இங்கு நகலாகக் காட்டப்படுகிறது.',
  'reports.tab.credit.hint': 'தொழிற்சாலை ஒவ்வொரு மாதமும் வழங்கியது: முன்பணம், கடன், உரம் மற்றும் தேயிலைப் பொதிகள். அங்கீகரிக்கப்பட்ட கோரிக்கைகள் மட்டும், முடிவெடுத்த மாதத்தின்படி.',
  'reports.credit.title': 'கடன் மற்றும் தேயிலைப் பொதிகள்',
  'reports.credit.advances': 'முன்பணங்கள்',
  'reports.credit.loans': 'கடன்கள்',
  'reports.credit.manure': 'உரம்',
  'reports.credit.teaPackets': 'தேயிலைப் பொதிகள்',
  'reports.credit.rejected': 'நிராகரிக்கப்பட்டவை',
  'reports.credit.approvedCount': 'அங்கீகரிக்கப்பட்டவை {{count}}',
  'reports.credit.rejectedTotal': 'காலத்தில் நிராகரிக்கப்பட்ட கோரிக்கைகள் {{count}}',
  'reports.credit.chartHint': 'ஒவ்வொரு பட்டியும் அந்த மாதத்தின் முன்பணம், கடன் மற்றும் உரம் சேர்ந்தது.',
  'reports.credit.empty': 'இன்னும் எதுவும் வழங்கப்படவில்லை',
  'reports.credit.emptyHint': 'கோரிக்கைகள் அங்கீகரிக்கப்பட்டவுடன், அவை மாதம் மாதமாக இங்கு மொத்தமாகக் காட்டப்படும்.',
  'reports.credit.notYet': 'இந்த அறிக்கை இந்தச் சேவையகத்தில் கிடைக்கவில்லை.',
