  'config.impact.creditRule.bad-installments':
    'குறைந்தது ஒரு திருப்பிச் செலுத்தும் தவணையையாவது வழங்கவும். இந்த வசதியை நிறுத்த, அதற்குப் பதிலாக “அம்சங்கள்” பகுதியில் நிறுத்தவும்.',

  /* ───────── தொழிற்சாலை அமைப்பிலிருந்து நகலெடுத்தல் (v2) ───────── */
  'shell.syncStale':
    'இந்த எண்கள் காலாவதியாகியிருக்கலாம். தொழிற்சாலை அமைப்பு கடைசியாக {{when}} அன்று வாசிக்கப்பட்டது, {{covers}} வரை உள்ளடக்கியது. ஒரு சப்ளையரிடம் இருப்பைச் சொல்வதற்கு முன் சரிபார்க்கவும்.',
  'shell.syncNever': 'இந்தக் கன்சோலுக்கு தொழிற்சாலை அமைப்பிலிருந்து இதுவரை எதுவும் வரவில்லை, எனவே கணக்குகளும் இருப்புகளும் இல்லாமலோ முழுமையற்றதாகவோ இருக்கலாம். ஒரு எண்ணைக் கூறும் முன் தொழிற்சாலை அமைப்பைச் சரிபார்க்கவும்.',
  'sync.freshAsOf':
    '{{when}} அன்று தொழிற்சாலை அமைப்பிலிருந்து வாசிக்கப்பட்டது, {{covers}} வரை உள்ளடக்கியது.',
  'dataStatus.title': 'தரவு நிலை',
  'dataStatus.subtitle': 'இந்தக் கன்சோலில் உள்ள எண்கள் எங்கிருந்து வருகின்றன, அவை எவ்வளவு புதியவை.',
