  'dataStatus.unknownBody': 'கன்சோலால் இப்போது ஒத்திசைவு நிலையைப் படிக்க முடியவில்லை, எனவே எண்கள் எவ்வளவு புதியவை என்று கூற முடியாது. அவை சேவையகத்திலிருந்து வந்த உண்மையான எண்கள்; ஒன்றைக் கூறும் முன் தொழிற்சாலை அமைப்பைச் சரிபார்த்து, சில நிமிடங்களில் மீண்டும் முயற்சிக்கவும்.',
  'dataStatus.chip.stale': 'எண்கள் பழையவை',
  'dataStatus.chipHint': 'காரணத்தைத் தரவு நிலைப் பக்கத்தில் பார்க்கவும்',
