  'dataStatus.heading.direct': 'தொழிற்சாலையின் பதிவுகளிலிருந்து நேரடியாக வாசிக்கப்படுகிறது',
  'dataStatus.directBody': 'இந்தக் கன்சோல் ஒரு நகல் அல்ல: இது தொழிற்சாலையின் சொந்தப் பதிவுகளை வாசிப்பதால், பின்தங்குவதற்கு ஒத்திசைவு எதுவும் இல்லை.',
  'dataStatus.howTitle': 'எண்கள் இங்கு வரும் விதம்',
  'dataStatus.howBody': 'கணக்குகள், விநியோகங்கள் மற்றும் இருப்புகள் தொழிற்சாலையின் சொந்த அமைப்பிலிருந்து அட்டவணைப்படி நகலெடுக்கப்படுகின்றன. இந்தக் கன்சோல் காட்டுவது அந்த நகலையே, நேரடி வாசிப்பை அல்ல. எனவே வழங்குநரிடம் ஒரு எண்ணைச் சொல்வதற்கு முன் மேலே உள்ள நேரத்தை எப்போதும் சரிபார்க்கவும்.',

