  'teaPackets.noPolicy.body':
    'இந்த வேண்டுகோள்கள் ஒரு பொட்டலத்திற்கு {{price}} என்ற இயல்பு விலையில் கணக்கிடப்படுகின்றன. தொழிற்சாலையின் சொந்த விலையை “அமைப்பு” பகுதியில் நிர்ணயிக்கவும்.',

