  'rates.deduction.byPointHint': 'தொழிற்சாலைக் கட்டணத்தை ({{rate}}) பயன்படுத்த ஒரு மையத்தை வெறுமையாக விடவும். சொந்தக் கட்டணம் உள்ள விநியோகஸ்தர் எங்கு வழங்கினாலும் அதையே செலுத்துவார்.',
  'rates.deduction.field.transportByPoint': '{{point}} போக்குவரத்து',
