  'records.transport.noteHint': 'இந்த விநியோகஸ்தர் ஏன் வேறு கட்டணம் செலுத்துகிறார். குறைந்தது 10 எழுத்துகள்; தணிக்கைப் பதிவில் வைக்கப்படும்.',
