  'config.bill.unit': 'ரூ. {{unit}} அலகுகள்',
  'config.bill.unitExample': 'ரூ. {{payable}} மீதி ரூ. {{paid}} ஆகச் செலுத்தப்பட்டு, ரூ. {{coins}} முன்கொண்டு செல்லப்படும்.',
  'config.bill.nextSerial': 'அடுத்த பில் எண் (வரிசை)',
  'config.bill.nextSerialHint': 'தொழிற்சாலையின் கடைசி காகிதப் பில்லுக்குப் பின் வரும் எண், ஆண்டு இல்லாமல். Console இன் சொந்த எண்களுக்கு வெறுமையாக விடவும்.',
  'config.bill.serialInvalid': '1 முதல் 999999 வரை ஒரு முழு எண்ணை உள்ளிடவும்.',
