  'config.interest.how': 'எளிய வட்டி. ஒவ்வொரு பில்லிலும், அந்த மாதத் தவணைக்குப் பின் இன்னும் செலுத்த வேண்டிய முன்பணத்திலிருந்து கணக்கிடப்படும். அது பில்லில் காட்டப்பட்டு, அடுத்த பில் வசூலிக்கும் தொகையுடன் சேர்க்கப்படும். மாற்றம் அடுத்து உருவாக்கப்படும் பில்லிலிருந்து பொருந்தும், வெளியிடப்பட்ட மாதத்துக்கு ஒருபோதும் இல்லை.',
